const b=(symbol,type)=>({symbol,type});
const defs=[];const add=(symbol,type,definition,binders=[],objects=[],depends_on=[])=>{const id="D"+String(defs.length+1).padStart(3,"0");defs.push({id,symbol,type,definition,binders,objects,depends_on,requires:[]});return id;};
add("Torus","compact measure space","Torus=R/(2*pi*Z), with measure dx/(2*pi) on [0,2*pi).");
add("Fourier","Fourier coefficient map","For a periodic integrable f and k in Z, Fourier(f)(k)=(2*pi)^(-1) integral_0^(2*pi) f(x) exp(-i*k*x) dx; write hat f(k). Extend by completion and distribution duality.",[b("f","periodic integrable function or distribution"),b("k","integer")],["Torus"],["D001"]);
add("H","family of complex Hilbert spaces","For real s, H^s(Torus) is the completion of trigonometric polynomials for ||f||_(H^s)^2=sum_(k in Z)(1+k^2)^s |hat f(k)|^2. Negative spaces are periodic distributions. L^2=H^0 with the normalized measure. Real means hat f(-k)=overline(hat f(k)); mean-zero means hat f(0)=0. Write ||.||_2 for ||.||_(L^2).",[b("s","real"),b("f","periodic function or distribution")],["Torus","Fourier"],["D001","D002"]);
add("Hdot","homogeneous Sobolev norms on the mean-zero subspaces","||f||_(dot H^s)^2=sum_(k!=0)|k|^(2*s)|hat f(k)|^2 for a mean-zero f. For s>=0, ||f||_(dot H^s)<=||f||_(H^s)<=2^(s/2)||f||_(dot H^s); for s<0, 2^(s/2)||f||_(dot H^s)<=||f||_(H^s)<=||f||_(dot H^s), by 1<=<k>/|k|<=sqrt(2).",[b("s","real"),b("f","mean-zero periodic distribution")],["Fourier","H"],["D002","D003"]);
add("S","one-parameter group of Fourier multipliers","S_t=exp(-t*partial_x^3), hat(S_t f)(k)=exp(i*t*k^3)*hat f(k). Thus S_(t+r)=S_t S_r, S_0=I and each S_t is an isometry on every H^s by its unit-modulus multiplier.",[b("t","real"),b("r","real"),b("f","periodic distribution"),b("k","integer"),b("s","real")],["Fourier","H"],["D002","D003"]);
add("P0","projection onto the constant functions","P0 f=hat f(0), the mean, identified with a constant function.",[b("f","periodic distribution")],["Fourier"],["D002"]);
add("P","projection onto the mean-zero functions","P=I-P0.",[],["P0"],["D006"]);
add("Dinv","inverse spatial derivative Fourier multiplier","Dinv=partial_x^(-1); hat(Dinv f)(k)=(i*k)^(-1)hat f(k) for k!=0 and zero for k=0. Dinv2=(Dinv)^2=partial_x^(-2). These formulas define maps H^s -> H^(s+1) and H^s -> H^(s+2), respectively.",[b("f","periodic distribution"),b("k","integer"),b("s","real")],["Fourier","H"],["D002","D003"]);
add("Ftau","quadratic numerical update family","For tau>0 and mean-zero f in L^2, Ftau(f)=(1/6)P[(S_tau Dinv f)^2]-(1/6)S_tau P[(Dinv f)^2].",[b("tau","positive real"),b("f","mean-zero L^2 function")],["H","P","S","Dinv"],["D003","D005","D007","D008"]);
add("Htau","higher-order numerical update family",{from_task:"material-001.md",start_line:29,end_line:33},[b("tau","positive real"),b("f","mean-zero L^2 function"),b("s","real endpoint variable")],["P","P0","S","Dinv","Ftau"],["D005","D006","D007","D008","D009"]);
add("Psi","unmodified time-step map and finite numerical trajectories","Psi_tau(f)=S_tau f+Ftau(f)+Htau(f), tau>0. For a positive integer Lsteps and tau=T/Lsteps, set t_n=n*tau and u^0=u_0, u^(n+1)=Psi_tau(u^n), 0<=n<Lsteps; v^n=S_(-t_n)u^n. No spatial frequency cutoff is applied. This is a finite recursion; its L^2 continuity and preservation properties are proved below.",[b("tau","positive real"),b("f","mean-zero L^2 function"),b("Lsteps","positive integer"),b("u_0","mean-zero L^2 function"),b("n","integer grid index")],["T","S","Ftau","Htau"],["D005","D009","D010"]);
add("Ple","Fourier spectral projection family","Ple_N f has coefficients 1_(|k|<=N)*hat f(k), N>=0; Pgt_N=I-Ple_N. These are used only in the proof and in initial-data approximation.",[b("N","nonnegative real"),b("f","periodic distribution"),b("k","integer")],["Fourier"],["D002"]);
add("Mavg","time averaging operator","Mavg_tau g=(1/tau) integral_0^tau g(s) ds, tau>0.",[b("tau","positive real"),b("g","integrable complex function on [0,tau]"),b("s","real integration variable")],[]);
add("eta","average covariance of two exponential phases",{from_task:"material-001.md",start_line:46,end_line:48},[b("alpha","real"),b("beta","real"),b("tau","positive real"),b("s","real integration variable")],["Mavg"],["D013"]);
add("Rem","polynomial trilinear averaged cubic remainder","For tau>0,t0>=0 and mean-zero trigonometric polynomials f_1,f_2,f_3, define hat(Rem_(t0,tau)(f_1,f_2,f_3))(k)=-tau/(18*i*k) sum_(a+b+c=k,a+b!=0) exp(-i*t0*Phi)*eta_tau(alpha,beta)*hat f_1(a)*hat f_2(b)*hat f_3(c) for k!=0, and zero at k=0. Here p=a+b, alpha=3*a*b*p, beta=3*k*c*p, Phi=alpha+beta=k^3-a^3-b^3-c^3. The notation R^n_(2,tau) means Rem_(n*tau,tau). The extension to Sobolev inputs is a proved conclusion below, not an assumed estimate.",[b("tau","positive real"),b("t0","nonnegative real"),b("f_1","mean-zero trigonometric polynomial"),b("f_2","mean-zero trigonometric polynomial"),b("f_3","mean-zero trigonometric polynomial"),b("k","integer")],["Fourier","eta"],["D002","D014"]);
add("pstar","positive real","pstar=23/14.");
add("X","space-time norm on intervals","For an interval I with length at most one, X(I) consists of L^infinity(I;L^2) functions with weak time derivative in L^infinity(I;H^(-pstar)); ||f||_(X(I))=||f||_(L^infinity(I;L^2))+||f'||_(L^infinity(I;H^(-pstar))). All time suprema of continuous functions use their continuous representatives; derivatives and L^infinity norms use essential suprema.",[b("I","compact real interval"),b("f","time-dependent periodic distribution")],["H","pstar"],["D003","D016"]);
add("B","time-dependent symmetric bilinear operator","B_t(f,g)=S_(-t) partial_x[(S_t f)(S_t g)], initially for smooth periodic inputs, and in H^(-pstar) for L^2 inputs by the bound proved below.",[b("t","real"),b("f","periodic function"),b("g","periodic function")],["S","H","pstar"],["D003","D005","D016"]);
add("J","time-dependent symmetric normal-form bilinear operator","J_t(f,g)=S_(-t)P[(S_t Dinv f)(S_t Dinv g)].",[b("t","real"),b("f","periodic function or suitable distribution"),b("g","periodic function or suitable distribution")],["S","P","Dinv"],["D005","D007","D008"]);
add("Ctri","time-integrated trilinear operator","Ctri_I(f,g,h)=integral_I S_(-t)P{P[(S_t f(t))(S_t g(t))]*(S_t Dinv h(t))} dt. For time-independent inputs suppress their t dependence. Initially use smooth spatial inputs, with piecewise smooth continuous time dependence; bounded extensions are justified by the explicit sources or estimates below.",[b("I","compact real interval"),b("f","time-dependent periodic function"),b("g","time-dependent periodic function"),b("h","time-dependent periodic function"),b("t","real integration variable")],["S","P","Dinv"],["D005","D007","D008"]);
add("Fstage","bilinear first-stage integral family","Fstage_(a,t)(f,g)=(1/2) integral_a^t B_s(f,g) ds for time-independent smooth mean-zero f,g and a<=t. Fstage_(a,t)(f) abbreviates Fstage_(a,t)(f,f).",[b("a","real"),b("t","real with t>=a"),b("f","smooth mean-zero periodic function"),b("g","smooth mean-zero periodic function"),b("s","real integration variable")],["B"],["D018"]);
add("Interp","step interpolation construction","For a>=0,tau>0 and smooth mean-zero f, on [a,a+tau] put F(t)=Fstage_(a,t)(f), z(t)=f+F(t), Cst(t)=integral_a^t B_s(f,F(s)) ds, Q(t)=(1/2)integral_a^t B_s(F(s),F(s)) ds, W=Q(a+tau)+Rem_(a,tau)(f,f,f), Vst(t)=f+F(t)+Cst(t)+Q(t)-((t-a)/tau)*W, Y(t)=Vst(t)-z(t). Interp_(a,tau;f) denotes this entire tuple (F,z,Cst,Q,W,Vst,Y). It is just these formulas, with no error estimates or endpoint matching granted.",[b("a","nonnegative real"),b("tau","positive real"),b("f","smooth mean-zero periodic function"),b("t","real in [a,a+tau]"),b("s","real integration variable")],["Fstage","Rem","B"],["D015","D018","D021"]);
add("KdV","initial-value equation and solution convention","KdV(u;u_0) means u_t+u_xxx=(1/2)partial_x(u^2), u(0)=u_0 on Torus, distributionally. The exact solution sought for real mean-zero u_0 in H^gamma is the unique real mean-zero C([0,T];H^gamma) solution obtained by smooth approximation. Its existence, uniqueness and quantitative bounds are established in N001; this predicate itself asserts no existence.",[b("u","time-dependent periodic distribution"),b("u_0","periodic distribution")],["Torus","H","T","gamma"],["D001","D003"]);
const spec={format_version:2,case_id:"benchmark",full_target:load("fulltarget"),conclusion:"There exist C>0 and tau_0>0 depending only on T,gamma,R such that, for every real mean-zero u_0 in H^gamma(Torus) with ||u_0||_(H^gamma)<=R and every positive integer Lsteps with tau=T/Lsteps<=tau_0, the exact solution of KdV(u;u_0) exists with the stipulated smooth-approximation meaning and the unfiltered recursion u^0=u_0, u^(n+1)=Psi_tau(u^n) satisfies max_(0<=n<=Lsteps)||u(n*tau)-u^n||_2<=C*tau^gamma. Both constants are uniform on the entire initial-data ball and independent of Fourier support and additional smoothness.",parameters:[b("T","real number"),b("gamma","real number"),b("R","real number")],hypotheses:[{id:"H001",statement:"T>0.",origin:"problem.md:88; target-selection.json full_target: for every T>0."},{id:"H002",statement:"0<gamma<=1.",origin:"problem.md:88; target-selection.json full_target."},{id:"H003",statement:"R>0.",origin:"problem.md:88; target-selection.json full_target."}],definitions:defs,logic:{classical:true,rules:["direct","forall_introduction","implication_introduction","case_elimination","exists_elimination","natural_induction","contradiction_classical"]},inputs:[],pins:{}};
