local("N1","positive real","definition","Let N1 be the largest of |a|,|b|,|c|,|d|.","S001","S002",["a","b","c","d"]),
local("N2","positive real","definition","Let N2 be the second largest magnitude.","S001","S002",["a","b","c","d"]),
